def classify_existing_media(apps, schema_editor):
    SiteMedia = apps.get_model('store', 'SiteMedia')
    for media in SiteMedia.objects.all().only('pk', 'file'):
        name = str(media.file).lower()
        if name.endswith(('.jpg', '.jpeg', '.png', '.webp', '.gif', '.ico', '.svg')):
            media_type = 'image'
        elif name.endswith(('.mp4', '.webm', '.mov')):
            media_type = 'video'
        elif name.endswith(('.pdf', '.doc', '.docx', '.xls', '.xlsx')):
            media_type = 'document'
        else:
            media_type = 'other'
        SiteMedia.objects.filter(pk=media.pk).update(media_type=media_type)


